import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"]
    cdc_events = inputs["cdc_events"]
    watermark = inputs["watermark"]

    # Determine watermark high_ts (assume single row; if empty, no filtering)
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = None

    # Filter to events not yet applied: event_ts > high_ts
    events = cdc_events.copy()
    if high_ts is not None:
        events = events[events["event_ts"] > high_ts]

    # Sort events globally by (event_ts, event_seq) - order across items doesn't matter
    # since items are processed independently, but we keep deterministic order.
    events = events.sort_values(by=["event_ts", "event_seq"], kind="mergesort")

    # Initialize state from target_snapshot: item_id -> (qty_on_hand, last_event_ts)
    state = {}
    for _, row in target_snapshot.iterrows():
        state[row["item_id"]] = (float(row["qty_on_hand"]), row["last_event_ts"])

    # Apply events per item in sequential order
    # Group events by item_id, preserving sorted order within each group
    for item_id, grp in events.groupby("item_id", sort=False):
        cur = state.get(item_id, None)
        for _, ev in grp.iterrows():
            op = ev["op"]
            qty = float(ev["qty"])
            ts = ev["event_ts"]

            if op == "R":
                base = cur[0] if cur is not None else 0.0
                new_qty = base + qty
                cur = (new_qty, ts)
            elif op == "A":
                cur = (qty, ts)
            elif op == "D":
                cur = None
            else:
                # Unknown op: no-op, but shouldn't occur per spec
                pass

        if cur is None:
            if item_id in state:
                del state[item_id]
        else:
            state[item_id] = cur

    # Build output DataFrame
    if len(state) == 0:
        new_snapshot = pd.DataFrame(
            {
                "item_id": pd.Series(dtype="int64"),
                "qty_on_hand": pd.Series(dtype="float64"),
                "last_event_ts": pd.Series(dtype="datetime64[us]"),
            }
        )
    else:
        rows = []
        for item_id, (qty, ts) in state.items():
            rows.append({"item_id": item_id, "qty_on_hand": qty, "last_event_ts": ts})
        new_snapshot = pd.DataFrame(rows)
        new_snapshot["item_id"] = new_snapshot["item_id"].astype("int64")
        new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype("float64")
        new_snapshot["last_event_ts"] = pd.to_datetime(new_snapshot["last_event_ts"]).astype(
            "datetime64[us]"
        )
        new_snapshot = new_snapshot.sort_values(by="item_id", kind="mergesort").reset_index(
            drop=True
        )

    return {"new_snapshot": new_snapshot}
